CREATE EXTENSION IF NOT EXISTS pgcrypto;
DO $$ BEGIN CREATE TYPE user_role AS ENUM ('citizen','responder','admin'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE incident_status AS ENUM ('active','acknowledged','dispatched','resolved','cancelled','false_alarm'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE address_review_state AS ENUM ('pending','approved','rejected'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sa_id_hash text UNIQUE NOT NULL,sa_id_enc bytea NOT NULL,full_name text NOT NULL,phone_e164 text UNIQUE NOT NULL,phone_verified_at timestamptz,role user_role NOT NULL DEFAULT 'citizen',stealth_enabled boolean NOT NULL DEFAULT true,silent_dispatch boolean NOT NULL DEFAULT false,high_accuracy_gps boolean NOT NULL DEFAULT true,token_version integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS otp_codes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),phone_e164 text NOT NULL,code_hmac bytea NOT NULL,expires_at timestamptz NOT NULL,attempts integer NOT NULL DEFAULT 0,sends_window_start timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now(),consumed_at timestamptz);
CREATE INDEX IF NOT EXISTS otp_phone_created_idx ON otp_codes(phone_e164,created_at DESC);
CREATE TABLE IF NOT EXISTS addresses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,street text NOT NULL,city text NOT NULL,province text NOT NULL,is_primary boolean NOT NULL DEFAULT false,review_state address_review_state NOT NULL DEFAULT 'pending',proof_key text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS emergency_contacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,name text NOT NULL,phone_e164 text NOT NULL,relationship text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS incidents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),category text NOT NULL,threat_level text NOT NULL CHECK(threat_level IN ('critical','high','medium')),status incident_status NOT NULL DEFAULT 'active',lat double precision NOT NULL CHECK(lat BETWEEN -90 AND 90),lng double precision NOT NULL CHECK(lng BETWEEN -180 AND 180),accuracy double precision,environment jsonb NOT NULL DEFAULT '[]'::jsonb,note text,assigned_unit text,eta_minutes integer,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS one_open_incident_per_user ON incidents(user_id) WHERE status IN ('active','acknowledged','dispatched');
CREATE INDEX IF NOT EXISTS incidents_status_created_idx ON incidents(status,created_at DESC);
CREATE TABLE IF NOT EXISTS incident_locations(id bigserial PRIMARY KEY,incident_id uuid NOT NULL REFERENCES incidents(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id),lat double precision NOT NULL CHECK(lat BETWEEN -90 AND 90),lng double precision NOT NULL CHECK(lng BETWEEN -180 AND 180),accuracy double precision,battery_pct integer,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS incident_locations_recent_idx ON incident_locations(incident_id,created_at DESC);
CREATE TABLE IF NOT EXISTS audit_log(id bigserial PRIMARY KEY,actor_user_id uuid REFERENCES users(id),incident_id uuid REFERENCES incidents(id),action text NOT NULL,details jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),incident_id uuid NOT NULL UNIQUE REFERENCES incidents(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id),title text NOT NULL,kind integer NOT NULL,priority integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now());

CREATE OR REPLACE FUNCTION bump_token_version_on_role_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.role IS DISTINCT FROM OLD.role THEN NEW.token_version := OLD.token_version + 1; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS users_role_token_version ON users;
CREATE TRIGGER users_role_token_version BEFORE UPDATE OF role ON users FOR EACH ROW EXECUTE FUNCTION bump_token_version_on_role_change();
